@startuml

class Employee {
  + identifying_number : string
  + name : string
  + address : string
}

class Owner {
  + identifying_number : string
  + name : string
  + address : string
  + phone : string
}

class Car {
  + license_plate : string
  + make : string
  + model : string
  + color : string
}

class PartAcc {
  + serial_number : string
  + price : double
  + category : string
}

class CarModel {}

class AssemblyService {
  + kms : int
  + work_hours : float
  + admission_date : date
  + finish_date : date
}

Owner "1" -- "*" Car : owns
Car "1" -- "*" AssemblyService : undergoes
AssemblyService "1" -- "1" Employee : responsible_employee
AssemblyService "*" -- "*" PartAcc : fitted_with
PartAcc "*" -- "1" CarModel : fits
Car "*" -- "1" CarModel : is_a_model_of

@enduml

